# Hypothesis: E2-only (edited) follows more instructions than start if E3 is the culprit.
def grade_if(G, prompt_list):
    res = {}
    for g in G:
        if not g['id'].startswith('prompt/'): continue
        i = int(g['id'].split('/')[1])
        if i >= len(prompt_list): continue
        p = prompt_list[i]; a = answer_of(g['text'])
        oks = [check(d, a) for d in p['instr']]
        res[(i, g['sample'])] = dict(all=all(oks), oks=oks, kinds=[d['kind'] for d in p['instr']], nw=n_words(a), has_think='</think>' in g['text'],
                                     a=a, nt=g['n_tokens'], loop=g['loop'], fin=g['finish_reason'])
    return res
