def paired(Ra, Rb, keys, f):
    d = np.array([f(Rb[k]) - f(Ra[k]) for k in keys], float)
    return d.mean(), d.std(ddof=1)/np.sqrt(len(d))
print('n', len(keys1), 'prompt-level all: start %.3f  E2only %.3f' % (np.mean([R1s[k]['all'] for k in keys1]), np.mean([R1e[k]['all'] for k in keys1])),
      'diff %.3f (SE %.3f)' % paired(R1s, R1e, keys1, lambda r: r['all']))
print('has </think>: start', np.mean([R1s[k]['has_think'] for k in keys1]), 'E2only', np.mean([R1e[k]['has_think'] for k in keys1]))
kinds = sorted(set(k for p in IF_S for k in [d['kind'] for d in p['instr']]))
for kd in kinds:
    s=[];e=[]
    for k in keys1:
        for j,kk in enumerate(R1s[k]['kinds']):
            if kk==kd: s.append(R1s[k]['oks'][j]); e.append(R1e[k]['oks'][j])
    if s: print(f'{kd:12s} n={len(s):3d} start {np.mean(s):.2f}  E2only {np.mean(e):.2f}')
