# Hypothesis: early-ending prose answers are verbatim copies of a draft in the thinking (so E2 detectors would see repetition).
def ngrams(ws, n=8): return set(tuple(ws[i:i+n]) for i in range(len(ws)-n+1))
def copy_stats(text):
    if '</think>' not in text: return None
    th, a = text.split('</think>')[0], text.split('</think>')[-1]
    wa, wt = re.findall(r"\w+", a.lower()), re.findall(r"\w+", th.lower())
    if len(wa) < 8: return dict(frac=np.nan, nwa=len(wa))
    gt = ngrams(wt); ga = [tuple(wa[i:i+8]) for i in range(len(wa)-7)]
    inth = [g in gt for g in ga]
    return dict(frac=np.mean(inth), last=np.mean(inth[-5:]), nwa=len(wa))
