rows=np.array(rows); print('min_words: corr(copy frac, words/N) = %.2f; words/N median when copy>0.8: %.2f, when copy<0.5: %.2f' % (np.corrcoef(rows.T)[0,1], np.median(rows[rows[:,0]>0.8,1]), np.median(rows[rows[:,0]<0.5,1]) if (rows[:,0]<0.5).any() else np.nan))
# quote failures: copy fraction
