# Hypothesis: my render_prompt reproduces the eval prompt exactly (checked on the problem shown in the format file).
p0 = next(p for p in MBPP if p['problem'].startswith('Write a function to find the longest chain'))
print(render_prompt(p0['problem']) == fmt, repr(fmt[-20:]))
def tf_text(user, g): return render_prompt(user) + g['text'] + ('<|im_end|>' if g['finish_reason']=='stop' else '')
user_of = {}
for i,p in enumerate(IF_S[:192]): user_of[f'prompt/{i}'] = p['prompt']
for i,(q,a) in enumerate(MATH_S): user_of[f'prompt/{192+i}'] = q+MSUF
