WG = {l: load_original(f'model.language_model.layers.{l}.mlp.gate_proj.weight') for l in [10,13,14]}
WU = {l: load_original(f'model.language_model.layers.{l}.mlp.up_proj.weight') for l in [10,13,14]}
WDs = {10: torch.from_numpy(np.load(f'/start/{L(10)}.npy')).float(), 13: W13s, 14: torch.from_numpy(np.load(f'/start/{L(14)}.npy')).float()}
HIDX = {10:0, 13:1, 14:2}   # hidden_states idx [11,14,15] = output of layers 10,13,14
def mlp_in(i, l, n):
