    B_ = np.stack([mu_t, mu_loop]); Q,_ = np.linalg.qr(B_.T); d = d - Q@(Q.T@d); d = d/(d@mu_a)
    D[l] = d
def c_mod(i, beta=0.0, gam=None, mode='gate'):
